let raw = $input.first().json.content.parts[0].text || "";

// Limpia los backticks y etiquetas ```json
raw = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

// Convierte a JSON
let parsed = JSON.parse(raw);

return parsed;

